"use client"

import * as React from "react"
import Link from "next/link"

import { cn } from "@/lib/utils"
import type { BillComparison, CompareRow } from "@/lib/policy/bill-compare-types"

import "./policy/diff-view.css"
import "./bill-compare.css"

// A bill's printings, each against the one before it, read top to bottom as
// one redline (2026-09-11). Each change happens at the reading line, two
// thirds down the screen: the lines it removes are struck through in red,
// left to right, and a beat behind the strike the lines it adds are marked in
// with a green highlighter as they come up from faded to full
// (bill-compare.css). Scrolling back undoes it, so an edit can be watched
// again. Unchanged text never moves.
//
// How it got here, from Brendan's notes the same night: the first build ran
// the page through ParticleScroll (html-in-canvas) so removed lines crumbled
// and added lines condensed out of sand. The crumbled lines were never
// readable, and the sand hid the new text until it settled. The page now uses
// no canvas at all — plain CSS on an ordinary record page, the same in every
// browser.
//
// The rows come from `lineDiff` in reflow mode, the diff the repository view
// uses: words compared, not lines, so a line that only re-wrapped in the
// reprint is context, and the changed words inside a line are marked. The
// palette is the repository view's (GitHub's Primer, diff-view.css).
//
// Two settings, which Typeset's Diff page puts in its footer (Brendan,
// 2026-09-11). Width: centred, the text column's own width capped near the
// printed measure; or full, every row across the whole pane, which lets the
// eye follow a coloured line from one side to the other. Lock: locked, a
// change once shown stays shown; unlocked, scrolling back undoes it.

export type CompareWidth = "centered" | "full"

/** The reading line, as a fraction of the viewport. */
const LINE = 0.68
/** Each line of a changed paragraph starts this long after the one above… */
const ROW_BEAT = 140
/** …unless that would make the paragraph outlast this. */
const ROW_SPAN = 1500
/** A run's sweep starts up to this far into its line's beat, by where it sits on the line. */
const SWEEP = 360
/** Additions start this long after the strike of the lines they replace. */
const AFTER_STRIKE = 320

/**
 * Sets each change when it reaches the reading line — at its first added
 * line, or its first removed line when nothing was added — and, unless
 * `locked`, clears it if the reader scrolls back. At the very bottom every
 * change on screen counts as reached, since the last ones can never rise that
 * far. The scroller is the window, or `root` itself when it is `contained`.
 */
function useChanges(root: HTMLElement | null, { locked, contained }: { locked: boolean; contained: boolean }) {
  React.useEffect(() => {
    if (!root) return
    const target: HTMLElement | Window = contained ? root : window
    const view = () =>
      contained
        ? { top: root.getBoundingClientRect().top, height: root.clientHeight, atEnd: root.scrollTop + root.clientHeight >= root.scrollHeight - 2 }
        : { top: 0, height: window.innerHeight, atEnd: window.scrollY + window.innerHeight >= document.documentElement.scrollHeight - 2 }
    const changes = new Map<string, { trigger: HTMLElement; rows: HTMLElement[] }>()
    root.querySelectorAll<HTMLElement>("[data-block]").forEach((row) => {
      const key = row.dataset.block!
      const entry = changes.get(key)
      if (!entry) changes.set(key, { trigger: row, rows: [row] })
      else {
        entry.rows.push(row)
        if (row.dataset.side === "add" && entry.trigger.dataset.side !== "add") entry.trigger = row
      }
    })
    const list = [...changes.values()]

    let frame = 0
    const update = () => {
      frame = 0
      const { top, height, atEnd } = view()
      const line = top + height * (atEnd ? 1 : LINE)
      for (const change of list) {
        const reached = change.trigger.getBoundingClientRect().top < line
        for (const row of change.rows) {
          const attr = row.dataset.side === "add" ? "data-arrived" : "data-struck"
          const shown = row.hasAttribute(attr)
          if (reached && !shown) row.setAttribute(attr, "")
          else if (!reached && shown && !locked) row.removeAttribute(attr)
        }
      }
    }
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(update)
    }
    update()
    target.addEventListener("scroll", schedule, { passive: true })
    window.addEventListener("resize", schedule)
    return () => {
      cancelAnimationFrame(frame)
      target.removeEventListener("scroll", schedule)
      window.removeEventListener("resize", schedule)
    }
  }, [root, locked, contained])
}

export function BillCompare({
  href,
  number,
  title,
  printings,
  passes,
  width = "centered",
  locked = true,
  contained = false,
  headless = false,
}: BillComparison & {
  width?: CompareWidth
  locked?: boolean
  /** Scroll inside its own box (Typeset's pane) rather than with the page. */
  contained?: boolean
  /** No header and no outer padding of its own: the docs page around it carries the title (Brendan, 2026-09-11: the same layout as every other page). */
  headless?: boolean
}) {
  const [root, setRoot] = React.useState<HTMLDivElement | null>(null)
  useChanges(root, { locked, contained })
  return (
    <div ref={setRoot} data-not-typeset="true" className={cn("w-full", !headless && "px-4 pt-8 pb-24 sm:px-8", contained && "h-full overflow-y-auto")}>
      {!headless && (
        <header className="mx-auto max-w-3xl">
          <Link href={href} className="font-mono text-sm text-muted-foreground hover:text-foreground">
            {number}
          </Link>
          <h1 className="mt-1 text-2xl font-semibold tracking-tight text-balance">{title}</h1>
          <p className="mt-3 text-sm text-muted-foreground">{printings.join(" → ")}</p>
        </header>
      )}
      {passes.map((pass, p) => (
        <section key={`${pass.from}-${pass.to}`} id={`pass-${p}`} className={cn(headless ? "mt-8 scroll-mt-24 first:mt-0" : "mt-12")}>
          <h2 className="mx-auto mb-4 max-w-3xl text-sm font-semibold">
            {pass.from} → {pass.to}
          </h2>
          <Redline rows={pass.rows} pass={p} width={width} />
        </section>
      ))}
    </div>
  )
}

const SIGN = { same: "", add: "+", del: "−" } as const

function Redline({ rows, pass, width }: { rows: CompareRow[]; pass: number; width: CompareWidth }) {
  // How many lines each change removes and adds, to pace its lines' beats.
  const counts = new Map<number, { del: number; add: number }>()
  for (const row of rows) {
    if (row.block === undefined || row.change === "same") continue
    const c = counts.get(row.block) ?? { del: 0, add: 0 }
    c[row.change] += 1
    counts.set(row.block, c)
  }
  const rowDelay = (row: CompareRow) => {
    const c = counts.get(row.block ?? -1) ?? { del: 0, add: 0 }
    const n = row.change === "add" ? c.add : c.del
    const beat = (row.order ?? 0) * Math.min(ROW_BEAT, ROW_SPAN / Math.max(n, 1))
    return Math.round(beat + (row.change === "add" && c.del ? AFTER_STRIKE : 0))
  }

  return (
    // Centred: the column is as wide as the text's longest line up to about
    // the printed measure, and a longer line (a federal text's run-together
    // header, say) wraps rather than widening the column for the whole bill.
    // Full: every row spans the pane.
    <div className={cn("gh-diff flex w-full bg-transparent", width === "centered" && "justify-center")}>
      <pre
        className={cn(
          "m-0 max-w-full p-0 font-mono text-[13px] leading-[1.35] text-foreground",
          width === "centered" ? "w-fit max-w-[min(100%,92ch)] whitespace-pre-wrap" : "w-full overflow-x-auto whitespace-pre"
        )}
      >
        {rows.map((row, index) => {
          const changed = row.change !== "same"
          return (
            <div
              key={index}
              data-block={changed && row.block !== undefined ? `${pass}:${row.block}` : undefined}
              data-side={changed ? row.change : undefined}
              style={changed ? ({ "--row-delay": `${rowDelay(row)}ms` } as React.CSSProperties) : undefined}
              className={cn(
                "flex",
                row.furniture && !changed && "opacity-40",
                row.change === "add" && "compare-added",
                row.change === "del" && "compare-removed"
              )}
            >
              <span aria-hidden className={cn("w-[3ch] shrink-0 text-center text-muted-foreground select-none", changed && "compare-sign")}>
                {SIGN[row.change]}
              </span>
              <span className="min-h-[1.35em] pr-4">
                <Marked row={row} />
              </span>
            </div>
          )
        })}
      </pre>
    </div>
  )
}

/**
 * The line with its changed words marked: a removal's struck runs — its
 * marked words, or the whole text when nothing narrower is marked — and an
 * addition's highlighted words. Each run's sweep starts in proportion to
 * where it sits on the line.
 */
function Marked({ row }: { row: CompareRow }) {
  const { text, change, marks } = row
  if (change === "same") return <>{text}</>
  const delay = (from: number) => ({ "--strike-delay": `${Math.round((from / Math.max(text.length, 1)) * SWEEP)}ms` }) as React.CSSProperties
  if (!marks?.length) {
    // A whole added line is marked by its row's own sweep.
    if (change === "add") return <>{text}</>
    const lead = text.length - text.trimStart().length
    return (
      <>
        {text.slice(0, lead)}
        <span className="compare-strike" style={delay(lead)}>
          {text.slice(lead)}
        </span>
      </>
    )
  }
  const pieces: React.ReactNode[] = []
  let at = 0
  marks.forEach((m, i) => {
    if (m.from > at) pieces.push(text.slice(at, m.from))
    pieces.push(
      <span key={i} className={cn("rounded-[3px]", change === "add" ? "compare-highlight" : "compare-strike compare-word")} style={delay(m.from)}>
        {text.slice(m.from, m.to)}
      </span>
    )
    at = m.to
  })
  if (at < text.length) pieces.push(text.slice(at))
  return <>{pieces}</>
}

// The shape a bill comparison arrives in — the printings, each pass, each
// row — apart from the server file that builds it, so the redline component
// can travel without the database behind it (2026-09-12).

/** A span of a line that changed, by character offset. */
export type Mark = { from: number; to: number }

export type CompareRow = {
  change: "same" | "add" | "del"
  text: string
  marks?: Mark[]
  /** Page furniture — running heads, page numbers — dimmed as the bill page dims it. */
  furniture?: boolean
  /** The change block a removed or added line belongs to, and its place among that block's removals or additions. */
  block?: number
  order?: number
}

export type ComparePass = { from: string; to: string; rows: CompareRow[] }

export type BillComparison = {
  href: string
  number: string
  title: string
  printings: string[]
  passes: ComparePass[]
}

/* A change's two states (2026-09-11). Until the change reaches the reading
   line, a removed line looks like any unchanged line and an added line sits
   faded, not yet arrived. When it does (components/bill-compare.tsx sets
   `data-struck` on the removed rows and `data-arrived` on the added ones), a
   red strike sweeps left to right across the cut words, and a beat behind it
   a green highlighter sweeps across the new line and its new words as the
   text comes up to full strength. Each run starts in proportion to where it
   sits on its line (--strike-delay), each line a beat after the one above
   (--row-delay). Scrolling back reverses both. */

.gh-diff {
  --compare-strike: #cf222e;
}
.dark .gh-diff {
  --compare-strike: #f85149;
}

/* Removed */

.compare-strike {
  background-image: linear-gradient(var(--compare-strike), var(--compare-strike));
  background-repeat: no-repeat;
  background-position: 0 55%;
  background-size: 0% 2px;
  transition:
    background-size 520ms cubic-bezier(0.23, 1, 0.32, 1) calc(var(--row-delay, 0ms) + var(--strike-delay, 0ms)),
    background-color 400ms ease-out var(--row-delay, 0ms);
}

.compare-word {
  background-color: transparent;
}

.compare-removed {
  background-color: transparent;
  transition: background-color 400ms ease-out var(--row-delay, 0ms);
}

.compare-removed[data-struck] {
  background-color: var(--gh-diff-del-line);
}

[data-struck] .compare-strike {
  background-size: 100% 2px;
}

[data-struck] .compare-word {
  background-color: var(--gh-diff-del-word);
}

/* Added */

.compare-added {
  opacity: 0.35;
  background-image: linear-gradient(var(--gh-diff-add-line), var(--gh-diff-add-line));
  background-repeat: no-repeat;
  background-size: 0% 100%;
  transition:
    opacity 400ms ease-out var(--row-delay, 0ms),
    background-size 600ms cubic-bezier(0.23, 1, 0.32, 1) var(--row-delay, 0ms);
}

.compare-added[data-arrived] {
  opacity: 1;
  background-size: 100% 100%;
}

.compare-highlight {
  background-image: linear-gradient(var(--gh-diff-add-word), var(--gh-diff-add-word));
  background-repeat: no-repeat;
  background-size: 0% 100%;
  transition: background-size 520ms cubic-bezier(0.23, 1, 0.32, 1) calc(var(--row-delay, 0ms) + var(--strike-delay, 0ms));
}

[data-arrived] .compare-highlight {
  background-size: 100% 100%;
}

/* Both */

.compare-sign {
  opacity: 0;
  transition: opacity 300ms ease-out var(--row-delay, 0ms);
}

[data-struck] .compare-sign,
[data-arrived] .compare-sign {
  opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  .compare-strike,
  .compare-removed,
  .compare-added,
  .compare-highlight,
  .compare-sign {
    transition: none;
  }
}

/* GitHub's diff, measured from github.com on 2026-09-03: Primer's diffBlob
   palette (light and dark) and the table's own measurements. Imported by
   diff-view.tsx. */

.gh-diff {
  --gh-diff-add-line: #dafbe1;
  --gh-diff-add-num: #aceebb;
  --gh-diff-add-word: #aceebb;
  --gh-diff-del-line: #ffebe9;
  --gh-diff-del-num: #ffcecb;
  --gh-diff-del-word: #ffcecb;
  --gh-diff-hunk-line: #ddf4ff;
  --gh-diff-hunk-num: #b6e3ff;
  --gh-diff-hunk-num-hover: #0969da;
  --gh-diff-hunk-fg-hover: #fff;
  --gh-diff-expander: #59636e;
  --gh-diff-empty: #f6f8fa;
  --gh-diff-bg: #fff;
  --gh-diff-fg: #1f2328;
  --gh-diff-muted: #59636e;
  --gh-diff-border: #d1d9e0;
  --gh-diff-accent: #0969da;
  --gh-diff-on-accent: #fff;
  --gh-diff-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
}
.dark .gh-diff {
  --gh-diff-add-line: #2ea04326;
  --gh-diff-add-num: #3fb9504d;
  --gh-diff-add-word: #2ea04366;
  --gh-diff-del-line: #f851491a;
  --gh-diff-del-num: #f851494d;
  --gh-diff-del-word: #f8514966;
  --gh-diff-hunk-line: #388bfd1a;
  --gh-diff-hunk-num: #0c2d6b;
  --gh-diff-hunk-num-hover: #1f6feb;
  --gh-diff-hunk-fg-hover: #fff;
  --gh-diff-expander: #9198a1;
  --gh-diff-empty: #151b23;
  --gh-diff-bg: #0d1117;
  --gh-diff-fg: #f0f6fc;
  --gh-diff-muted: #9198a1;
  --gh-diff-border: #3d444d;
  --gh-diff-accent: #1f6feb;
  --gh-diff-on-accent: #fff;
}

/* The diff table itself: GitHub's measurements (apps/web/components/policy/diff-view.tsx). */
.gh-diff .gh-table {
  table-layout: fixed;
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
  line-height: 21px;
  tab-size: 4;
}
.gh-diff td {
  vertical-align: top;
  padding: 0;
}
.gh-diff .gh-num {
  width: 40px;
  min-width: 40px;
  height: 24px;
  text-align: center;
  font-size: 12px;
  line-height: 24px;
  color: var(--gh-diff-fg);
  user-select: none;
  font-family: var(--gh-diff-mono);
}
.gh-diff .gh-text {
  position: relative;
  padding-right: 24px;
  min-height: 24px;
}
.gh-diff .gh-line {
  display: block;
  font-family: var(--gh-diff-mono);
  font-size: 12px;
  line-height: 24px;
}
.gh-diff .gh-marker {
  float: left;
  width: 15px;
  padding-right: 8px;
  user-select: none;
  text-align: center;
}
.gh-diff .gh-inner {
  white-space: pre-wrap;
  word-break: break-word;
  min-height: 24px;
  padding-left: 23px;
}
.gh-diff .gh-marker + .gh-inner {
  padding-left: 0;
  margin-left: 23px;
}
.gh-diff .gh-x {
  border-radius: 3px;
}
.gh-diff .gh-hunk {
  height: 24px;
  line-height: 24px;
}
.gh-diff .gh-hunk-text {
  display: block;
  padding: 0 24px;
  font-family: var(--gh-diff-mono);
  font-size: 12px;
  line-height: 24px;
  white-space: pre;
}
.gh-diff .gh-expander {
  display: flex;
  flex-shrink: 0;
  align-items: stretch;
  justify-content: center;
}
.gh-diff .gh-expander button {
  display: grid;
  place-items: center;
  flex: 1;
  height: 24px;
  color: var(--gh-diff-expander);
}
.gh-diff .gh-expander button:hover {
  background: var(--gh-diff-hunk-num-hover);
  color: var(--gh-diff-hunk-fg-hover);
}
.gh-diff .gh-plus {
  position: absolute;
  top: 1px;
  left: -10px;
  z-index: 1;
  display: none;
  width: 22px;
  height: 22px;
  place-items: center;
  border-radius: 6px;
  background: var(--gh-diff-accent);
  color: var(--gh-diff-on-accent);
  box-shadow: 0 1px 0 rgba(31, 35, 40, 0.1);
}
.gh-diff .gh-caret {
  position: absolute;
  top: 1px;
  right: 4px;
  display: none;
  width: 22px;
  height: 22px;
  place-items: center;
  border-radius: 6px;
  border: 1px solid var(--gh-diff-border);
  background: var(--gh-diff-bg);
  color: var(--gh-diff-muted);
}
.gh-diff .gh-row:hover .gh-plus,
.gh-diff .gh-row:hover .gh-caret,
.gh-diff .gh-plus:focus-visible,
.gh-diff .gh-caret:focus-visible,
.gh-diff .gh-caret[aria-expanded="true"] {
  display: grid;
}
.gh-diff .gh-plus:hover {
  transform: scale(1.1);
}

/* The row the reader selected: GitHub's 2px accent ring around the row. */
.gh-diff .gh-row[data-selected] td {
  box-shadow: inset 0 2px 0 var(--gh-diff-accent), inset 0 -2px 0 var(--gh-diff-accent);
}
.gh-diff .gh-row[data-selected] td:first-child {
  box-shadow: inset 2px 2px 0 var(--gh-diff-accent), inset 0 -2px 0 var(--gh-diff-accent), inset 2px 0 0 var(--gh-diff-accent);
}
.gh-diff .gh-row[data-selected] td:last-child {
  box-shadow: inset -2px 2px 0 var(--gh-diff-accent), inset 0 -2px 0 var(--gh-diff-accent), inset -2px 0 0 var(--gh-diff-accent);
}
.gh-diff .gh-row[data-selected] .gh-plus,
.gh-diff .gh-row[data-selected] .gh-caret {
  display: grid;
}
/* Compact line height: GitHub's 20px rows. */
.gh-diff.gh-compact .gh-num,
.gh-diff.gh-compact .gh-line,
.gh-diff.gh-compact .gh-inner,
.gh-diff.gh-compact .gh-hunk,
.gh-diff.gh-compact .gh-hunk-text,
.gh-diff.gh-compact .gh-marker {
  line-height: 20px;
  min-height: 20px;
}
.gh-diff.gh-compact .gh-num,
.gh-diff.gh-compact .gh-hunk,
.gh-diff.gh-compact .gh-expander button {
  height: 20px;
}
